116	    /// Prepare the inputs for use. Allocations happen on the arena.
117	    pub fn prepareInput(
118	        self: *ThreadEnterState,
119	    ) (Allocator.Error || error{InputNotFound})![]const Input {
120	        const alloc = self.arena.allocator();
121	
122	        var inputs: std.ArrayList(Input) = try .initCapacity(
123	            alloc,
124	            self.input.list.items.len,
125	        );
126	        errdefer for (inputs.items) |item| item.deinit();
127	
128	        for (self.input.list.items) |item| {
129	            inputs.appendAssumeCapacity(switch (item) {
130	                .raw => |v| .{ .string = v },
131	                .path => |path| file: {
132	                    const f = std.Io.Dir.cwd().openFile(
133	                        global.io(),
134	                        path,
135	                        .{},
136	                    ) catch |err| {
137	                        log.warn("failed to open input file={s} err={}", .{
138	                            path,
139	                            err,
140	                        });
141	                        return error.InputNotFound;
142	                    };
143	
144	                    break :file .{ .file = f };
145	                },
146	            });
147	        }
148	
149	        return inputs.items;
150	    }
151	
152	    const Input = union(enum) {
153	        string: []const u8,
154	        file: std.Io.File,
155	
156	        fn deinit(self: Input) void {
157	            switch (self) {
158	                .string => {},
159	                .file => |f| f.close(global.io()),
160	            }
161	        }
162	    };
163	};
